def trim(a):
    while len(a) > 1 and a[-1] == 0:
        a = a[:-1]
    return a or [0]


def poly_divmod(f, g, p):
    """(q, r) with f = q*g + r over Z_p; lists lowest degree first."""
    g = trim([c % p for c in g])
    if g == [0]:
        raise ZeroDivisionError("division by the zero polynomial")
    inv = pow(g[-1], -1, p)           # the field step: 1 / leading coeff
    r = [c % p for c in f]
    n = len(g)
    q = [0] * max(1, len(r) - n + 1)
    for k in range(len(r) - n, -1, -1):
        c = r[k + n - 1] * inv % p
        q[k] = c
        for i, b in enumerate(g):
            r[i + k] = (r[i + k] - c * b) % p
    return trim(q), trim(r)
